package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.*; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.*;
@Document("lots") public class Lot { @Id public String id; @Indexed(unique=true) public String lotId; @Indexed public String collectorId; @Indexed public String category; public String description; public double quantity; public double estimatedWeight; public String unit="kg"; public String condition; public List<String> imageUrls=new ArrayList<>(); public String pickupAddress; public Double latitude,longitude; @Indexed public LotStatus status=LotStatus.DRAFT; public String acceptedQuotationId; public List<StatusEvent> history=new ArrayList<>(); @CreatedDate public Instant createdAt; @LastModifiedDate public Instant updatedAt; public record StatusEvent(LotStatus from,LotStatus to,String actorId,Instant at,String note){} }
